-- Migration reservation 9340. PRIVATE DISABLED candidate; not applied.
-- min_level=0/faction=0 placeholders MUST NOT be activated as historical policy.
-- XP1000 is an approved configurable PEQ default. Parent has no item reward.
-- No drops, NPC placements, character data or shared migration registry changed.
CREATE PROCEDURE install_gearing_up_9340_candidate()
BEGIN
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 IF (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('tasks','task_activities','achievement_criteria') AND ENGINE='InnoDB')<>3
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Gearing Up requires transactional content tables'; END IF;
 START TRANSACTION;
 IF EXISTS(SELECT 1 FROM tasks WHERE id BETWEEN 3044001 AND 3044008)
 OR EXISTS(SELECT 1 FROM task_activities WHERE taskid BETWEEN 3044001 AND 3044008)
 OR EXISTS(SELECT 1 FROM achievement_criteria WHERE achievement_id=500120600 AND component_type=1 AND component_id BETWEEN 50353 AND 50360)
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Gearing Up ID collision: no rows installed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM npc_types WHERE id=436006 AND name='#Tabazin_Gearflinger')
 OR (SELECT COUNT(*) FROM items WHERE id BETWEEN 36476 AND 36488 AND stackable=1 AND stacksize=20 AND nodrop=0)<>13
 OR NOT EXISTS(SELECT 1 FROM items WHERE id=36485 AND Name='Steel Wire' AND lore='A piece of steel wire')
 OR NOT EXISTS(SELECT 1 FROM items WHERE id=36486 AND Name='Oil Can' AND lore='A can of oil')
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Gearing Up native dependencies missing'; END IF;
 COMMIT;
END;
CALL install_gearing_up_9340_candidate();
DROP PROCEDURE install_gearing_up_9340_candidate;
